## Solution
```java[]
class Solution {
    public int[] pascalTriangleII(int r) {
        List<List<Integer>> ans = new ArrayList<>();

        for (int i = 0; i < r; i++) {
            List<Integer> current = new ArrayList<>();
            current.add(1);

            for (int j = 1; j < i; j++) {
                current.add(ans.get(i - 1).get(j - 1)
                         + ans.get(i - 1).get(j));
            }

            if (i > 0) {
                current.add(1);
            }

            ans.add(current);
        }

        List<Integer> row = ans.get(r - 1);

        int[] result = new int[row.size()];

        for (int i = 0; i < row.size(); i++) {
            result[i] = row.get(i);
        }

        return result;
    }
}
