class Solution {
public:
    vector<int> pascalTriangleII(int r) {

        vector<int> ans;

        long long res= 1;
        ans.push_back(1);
        for(int i=0;i<r-1;i++){
            res = res *(r-i-1);
            res = res /(i+1);
            ans.push_back(res);
        }
        return ans;
    }
};
