    # Returns the value at the requested Pascal position.
    def pascal_value(self, r: int, c: int) -> int:
        triangle: list[list[int]] = [[1]]

        # Build every row needed to reach the requested row.
        for row in range(2, r + 1):
            current: list[int] = [1] * row

            # Fill interior cells from adjacent values in the previous row.
            for col in range(1, row - 1):
                current[col] = triangle[row - 2][col - 1] + triangle[row - 2][col]

            triangle.append(current)

        return triangle[r - 1][c - 1]


